// Independent from-scratch AES (ECB single block) for cross-validation only.
const SBOX = new Uint8Array(256), RSBOX = new Uint8Array(256);
(function(){
  let p=1,q=1;
  do {
    p = p ^ ((p<<1)&0xff) ^ ((p&0x80)?0x1b:0);
    q ^= q<<1; q ^= q<<2; q ^= q<<4; q&=0xff; if(q&0x80) q^=0x09;
    const x = q ^ ((q<<1)|(q>>>7)) ^ ((q<<2)|(q>>>6)) ^ ((q<<3)|(q>>>5)) ^ ((q<<4)|(q>>>4));
    SBOX[p] = (x ^ 0x63) & 0xff;
  } while (p!==1);
  SBOX[0]=0x63;
  for(let i=0;i<256;i++) RSBOX[SBOX[i]]=i;
})();
const xt = (a,b)=>{let r=0;for(let i=0;i<8;i++){if(b&1)r^=a;const h=a&0x80;a=(a<<1)&0xff;if(h)a^=0x1b;b>>=1;}return r;};
export function expandKey(key){
  const Nk=key.length/4, Nr=Nk+6, w=new Uint8Array(16*(Nr+1));
  w.set(key,0);
  let rcon=1;
  for(let i=Nk;i<4*(Nr+1);i++){
    let t=[w[(i-1)*4],w[(i-1)*4+1],w[(i-1)*4+2],w[(i-1)*4+3]];
    if(i%Nk===0){ t=[SBOX[t[1]]^rcon,SBOX[t[2]],SBOX[t[3]],SBOX[t[0]]]; rcon=xt(rcon,2); }
    else if(Nk>6 && i%Nk===4){ t=t.map(b=>SBOX[b]); }
    for(let j=0;j<4;j++) w[i*4+j]=w[(i-Nk)*4+j]^t[j];
  }
  return {w,Nr};
}
export function encryptBlock(key, block){
  const {w,Nr}=expandKey(key);
  const s=Uint8Array.from(block);
  const ark=r=>{for(let i=0;i<16;i++)s[i]^=w[r*16+i];};
  ark(0);
  for(let r=1;r<=Nr;r++){
    for(let i=0;i<16;i++) s[i]=SBOX[s[i]];
    // ShiftRows (column-major state: s[c*4+r])
    const t=Uint8Array.from(s);
    for(let row=1;row<4;row++) for(let c=0;c<4;c++) s[c*4+row]=t[((c+row)%4)*4+row];
    if(r!==Nr){
      for(let c=0;c<4;c++){
        const o=c*4, a0=s[o],a1=s[o+1],a2=s[o+2],a3=s[o+3];
        s[o]  =xt(a0,2)^xt(a1,3)^a2^a3;
        s[o+1]=a0^xt(a1,2)^xt(a2,3)^a3;
        s[o+2]=a0^a1^xt(a2,2)^xt(a3,3);
        s[o+3]=xt(a0,3)^a1^a2^xt(a3,2);
      }
    }
    ark(r);
  }
  return s;
}
