export function pyBytesRepr(buf){
  const hasS=buf.includes(0x27), hasD=buf.includes(0x22);
  const q=(hasS&&!hasD)?'"':"'";
  let s='b'+q;
  for(const b of buf){
    if(b===0x5c) s+='\\\\';
    else if(b===q.charCodeAt(0)) s+='\\'+q;
    else if(b===0x09) s+='\\t';
    else if(b===0x0a) s+='\\n';
    else if(b===0x0d) s+='\\r';
    else if(b>=0x20 && b<0x7f) s+=String.fromCharCode(b);
    else s+='\\x'+b.toString(16).padStart(2,'0');
  }
  return s+q;
}
