import { run } from './run.mjs';
import { encryptBlock } from './aes.mjs';
import { pyBytesRepr } from './repr.mjs';
const PRINT="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,-.:;<=>?@[]^_{|}~ '\"\\/";
let seed=12345; const rnd=()=>{seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff;};
const rs=n=>Array.from({length:n},()=>PRINT[Math.floor(rnd()*PRINT.length)]).join('');
function predict(key,data){
  const kb=Buffer.from(key,'utf8'), db=Buffer.from(data,'utf8');
  let out='';
  for(let i=0;i<db.length;i+=16) out+=pyBytesRepr(encryptBlock(kb,db.subarray(i,i+16)))+'\n';
  return out;
}
let n=0, bad=0;
for(const ks of [16,24,32]) for(const dl of [16,32,48,64,80]) for(let t=0;t<8;t++){
  let key,data;
  do { key=rs(ks); } while(Buffer.byteLength(key)!==ks);
  do { data=rs(dl); } while(Buffer.byteLength(data)!==dl);
  const r=run(['--key',key,'--data',data]);
  const p=predict(key,data);
  n++;
  if(r.code!==0 || r.stdout!==p){ bad++; console.log('MISMATCH ks='+ks+' dl='+dl); console.log(' key='+JSON.stringify(key)); console.log(' data='+JSON.stringify(data)); console.log(' got='+JSON.stringify(r.stdout)); console.log(' exp='+JSON.stringify(p)); console.log(' err='+JSON.stringify(r.stderr)); }
}
console.log('checked '+n+' random cases, mismatches='+bad);
